<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
type Dataset={id:string;name:string;sql:string};type Cell={row:number;column:number;value:string;style?:Style;binding?:Binding};type Style={bold?:boolean;color?:string;background?:string;align?:string};type Binding={datasetId:string;field:string;expansion:'NONE'|'DOWN'|'RIGHT';groupBy?:string;aggregate:'NONE'|'SUM'|'COUNT'};type Definition={rows:number;columns:number;cells:Cell[];merges:{startRow:number;startColumn:number;endRow:number;endColumn:number}[];rowHeights:Record<number,number>;columnWidths:Record<number,number>};type Template={id:string;name:string;definition:Definition};
const apiKey=ref(sessionStorage.getItem('smartbi.apiKey')||''),datasets=ref<Dataset[]>([]),templates=ref<Template[]>([]),currentId=ref(''),name=ref('销售报表'),mode=ref<'design'|'preview'>('design'),notice=ref(''),error=ref(''),parameters=ref('{"minimum":100}'),rendered=ref<any>(null),selected=reactive({row:0,column:0});
const definition=reactive<Definition>({rows:12,columns:6,cells:[{row:0,column:0,value:'销售明细',style:{bold:true,background:'#dbeafe'}},{row:2,column:0,value:'地区'},{row:2,column:1,value:'金额'}],merges:[{startRow:0,startColumn:0,endRow:0,endColumn:2}],rowHeights:{},columnWidths:{}});const edit=reactive({value:'',bold:false,background:'#ffffff',datasetId:'',field:'',expansion:'NONE' as Binding['expansion'],groupBy:'',aggregate:'NONE' as Binding['aggregate']});
const selectedCell=computed(()=>definition.cells.find(c=>c.row===selected.row&&c.column===selected.column));
async function api(path:string,init?:RequestInit){sessionStorage.setItem('smartbi.apiKey',apiKey.value);const r=await fetch(path,{...init,headers:{'Content-Type':'application/json','X-API-Key':apiKey.value,...init?.headers}});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.message||`HTTP ${r.status}`);return b}
async function load(){await act(async()=>{[datasets.value,templates.value]=await Promise.all([api('/api/v1/datasets'),api('/api/v1/report-templates')]);notice.value='资源已加载'})}
function choose(r:number,c:number){selected.row=r;selected.column=c;const x=definition.cells.find(v=>v.row===r&&v.column===c);edit.value=x?.value||'';edit.bold=!!x?.style?.bold;edit.background=x?.style?.background||'#ffffff';edit.datasetId=x?.binding?.datasetId||'';edit.field=x?.binding?.field||'';edit.expansion=x?.binding?.expansion||'NONE';edit.groupBy=x?.binding?.groupBy||'';edit.aggregate=x?.binding?.aggregate||'NONE'}
function apply(){let x=selectedCell.value;if(!x){x={row:selected.row,column:selected.column,value:''};definition.cells.push(x)}x.value=edit.value;x.style={bold:edit.bold,background:edit.background};x.binding=edit.datasetId&&edit.field?{datasetId:edit.datasetId,field:edit.field,expansion:edit.expansion,groupBy:edit.groupBy||undefined,aggregate:edit.aggregate}:undefined}
function cellAt(r:number,c:number){return definition.cells.find(x=>x.row===r&&x.column===c)}function label(c:number){return String.fromCharCode(65+c)}
async function save(){apply();await act(async()=>{const body=JSON.stringify({name:name.value,definition});const t=await api(currentId.value?`/api/v1/report-templates/${currentId.value}`:'/api/v1/report-templates',{method:currentId.value?'PUT':'POST',body});currentId.value=t.id;notice.value='模板已保存，可重新打开';await load()})}
function open(t:Template){currentId.value=t.id;name.value=t.name;Object.assign(definition,JSON.parse(JSON.stringify(t.definition)));mode.value='design';choose(0,0)}
async function preview(){if(!currentId.value)await save();await act(async()=>{rendered.value=await api(`/api/v1/report-templates/${currentId.value}/render`,{method:'POST',body:JSON.stringify({parameters:JSON.parse(parameters.value)})});mode.value='preview';notice.value='服务端确定性渲染完成'})}
function renderedAt(r:number,c:number){return rendered.value?.cells?.find((x:any)=>x.row===r&&x.column===c)}
function mergeRight(){definition.merges=definition.merges.filter(m=>!(selected.row>=m.startRow&&selected.row<=m.endRow&&selected.column>=m.startColumn&&selected.column<=m.endColumn));if(selected.column<definition.columns-1)definition.merges.push({startRow:selected.row,startColumn:selected.column,endRow:selected.row,endColumn:selected.column+1})}
async function act(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}onMounted(load)
</script>
<template><main><header><div><span class="eyebrow">SMARTBI SPREADSHEET REPORT</span><h1>电子表格报表设计器</h1><p>模板持久化、数据集绑定与服务端确定性扩展。</p></div><div class="auth"><input v-model="apiKey" type="password" placeholder="API Key"><button class="ghost" @click="load">加载</button></div></header><p v-if="error" class="error">{{error}}</p><p v-if="notice" class="success">{{notice}}</p><nav><button :class="{active:mode==='design'}" @click="mode='design'">设计态</button><button :class="{active:mode==='preview'}" @click="preview">预览态</button><input v-model="name" aria-label="模板名称"><button @click="save">保存模板</button></nav>
<section class="workspace"><aside><h2>模板</h2><button class="wide ghost" @click="currentId='';name='新报表'">新建</button><button v-for="t in templates" :key="t.id" class="template" @click="open(t)">{{t.name}}</button><h2>渲染参数</h2><textarea v-model="parameters" rows="5"/></aside>
<div class="sheet-wrap"><div v-if="mode==='design'" class="sheet" :style="{gridTemplateColumns:`42px repeat(${definition.columns}, 112px)`}"><div class="corner"></div><div v-for="c in definition.columns" :key="`h${c}`" class="head">{{label(c-1)}}</div><template v-for="r in definition.rows" :key="r"><div class="head">{{r}}</div><button v-for="c in definition.columns" :key="c" class="cell" :class="{selected:selected.row===r-1&&selected.column===c-1,bound:cellAt(r-1,c-1)?.binding}" :style="cellAt(r-1,c-1)?.style" @click="choose(r-1,c-1)">{{cellAt(r-1,c-1)?.value}}</button></template></div>
<div v-else-if="rendered" class="sheet" :style="{gridTemplateColumns:`42px repeat(${rendered.columns}, 112px)`}"><div class="corner"></div><div v-for="c in rendered.columns" :key="`p${c}`" class="head">{{label(c-1)}}</div><template v-for="r in rendered.rows" :key="r"><div class="head">{{r}}</div><div v-for="c in rendered.columns" :key="c" class="cell preview" :style="renderedAt(r-1,c-1)?.style">{{renderedAt(r-1,c-1)?.value}}</div></template></div></div>
<aside v-if="mode==='design'" class="inspector"><h2>单元格 {{label(selected.column)}}{{selected.row+1}}</h2><label>内容 / 公式<input v-model="edit.value" placeholder="文本或 =A1+B1"></label><div class="row"><label><input v-model="edit.bold" type="checkbox"> 粗体</label><label>底色<input v-model="edit.background" type="color"></label></div><button class="ghost wide" @click="mergeRight">向右合并</button><h2>数据集绑定</h2><label>数据集<select v-model="edit.datasetId"><option value="">无</option><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>字段<input v-model="edit.field" placeholder="region"></label><label>扩展<select v-model="edit.expansion"><option value="NONE">不扩展</option><option value="DOWN">纵向</option><option value="RIGHT">横向</option></select></label><label>汇总<select v-model="edit.aggregate"><option value="NONE">无</option><option value="SUM">SUM</option><option value="COUNT">COUNT</option></select></label><label v-if="edit.aggregate!=='NONE'">分组字段<input v-model="edit.groupBy"></label><button class="wide" @click="apply">应用单元格</button></aside></section></main></template>
